    public static bool IsInteraction(string name) => TryGet(name, out var item) && item.Effect != ToolEffect.ReadOnly && item.Feature != BrowserFeature.Close;
    public static bool TryGet(string name, out BrowserToolMetadata metadata) => Tools.TryGetValue(name, out metadata!);
